/* GB grudzien — jedna warstwa oryginalnych szklanych lamp i zatwierdzone stroiki 70%.
   Dodatek nie zmienia rozliczen, zakazow, zegara ani juz istniejacych animacji grudniowych.
*/
(()=>{'use strict';
if(window.__gbDecemberDecor2026) return;window.__gbDecemberDecor2026=true;
const IMG={
  wire:'data:image/webp;base64,',
  pine:'data:image/webp;base64,',
  left:'data:image/webp;base64,',
  right:'data:image/webp;base64,'
};
const KEY='gb-grudzien-motyw-v1';
const modes=['wave','steady','breath','random','alternate','mix'];
const DEFAULT={power:true,mode:'wave',brightness:100,glass:20,saturation:100};
let pref={...DEFAULT};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&typeof saved==='object'){
 pref.power=typeof saved.power==='boolean'?saved.power:DEFAULT.power;
 pref.mode=modes.includes(saved.mode)?saved.mode:DEFAULT.mode;
 pref.brightness=(saved.brightness===undefined)?DEFAULT.brightness:Math.max(0,Math.min(100,Number(saved.brightness)||0));
 pref.glass=(saved.glass===undefined)?DEFAULT.glass:Math.max(0,Math.min(100,Number(saved.glass)||0));
 pref.saturation=Math.max(0,Math.min(500,Number(saved.saturation??100)||0));
}}catch(e){}
const preview=(location.hostname.endsWith('app.github.dev') || location.hostname==='localhost' || location.protocol==='file:') && new URLSearchParams(location.search).get('gb-grudzien-podglad')==='1';
const december=()=>new Date().getMonth()===11 || preview;
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(pref))}catch(e){}};
const header=document.getElementById('gbHeader'),legend=document.querySelector('.app .legend'),settings=document.getElementById('gbAppSettings');
if(!header||!legend||!settings)return;
const css=`
#gbHeader{position:relative!important}
#gbHeader .gb-title,#gbHeader .gb-actions,#gbHeader .gb-ban{position:relative;z-index:4!important}
#gb-dec-wire,#gb-dec-pine,#gb-dec-glow{position:absolute;left:0;top:0;width:100%;height:auto;pointer-events:none;max-height:100px;object-fit:fill}
#gb-dec-wire{z-index:2;transform:translateZ(0)}
#gb-dec-pine{z-index:3}
#gb-dec-glow{z-index:3;max-height:none;mix-blend-mode:screen}
.gb-dec-hidden{display:none!important}
.app .legend.gb-dec-legend{position:relative;isolation:isolate}
.gb-dec-legend .gb-dec-stroik{position:absolute;pointer-events:none;height:auto;z-index:0;bottom:calc(100% - 17px);filter:drop-shadow(0 1px 1px #33415555)}
.gb-dec-legend .gb-dec-stroik-left{width:min(21vw,116px);left:-7px}
.gb-dec-legend .gb-dec-stroik-right{width:min(23vw,126px);right:-7px}
.gb-dec-menu-heading{font:700 17px system-ui,Arial;color:#183b5e;margin:2px 0 12px}
.gb-dec-settings{display:grid;gap:12px;color:#243347}
.gb-dec-settings label{display:block;font:600 14px system-ui,Arial}
.gb-dec-settings .gb-dec-line{display:flex;align-items:center;justify-content:space-between;gap:12px}
.gb-dec-settings output{font-variant-numeric:tabular-nums;color:#116ca3}
.gb-dec-settings select,.gb-dec-settings input[type=range]{width:100%;accent-color:#167eb4;box-sizing:border-box}
.gb-dec-settings select{padding:10px;border-radius:10px;border:1px solid #b4c7da;font:14px system-ui,Arial;background:white;color:#163453}
.gb-dec-settings input[type=checkbox]{width:22px;height:22px;accent-color:#167eb4}
.gb-dec-card{padding:12px;border:1px solid #d3e0ec;border-radius:12px;background:#f7fbff}
.gb-dec-back{padding:12px;background:#155f8d;color:#fff;width:100%;border:0;border-radius:10px;font:600 15px system-ui}
@media print{#gb-dec-wire,#gb-dec-pine,#gb-dec-glow,.gb-dec-stroik{display:none!important}}
`;
const sheet=document.createElement('style');sheet.id='gb-dec-style';sheet.textContent=css;document.head.appendChild(sheet);
const makeImage=(src,id,classname,parent)=>{const im=new Image();im.id=id;im.src=src;im.alt='';im.className=classname||'';im.setAttribute('aria-hidden','true');parent.appendChild(im);return im};
const wire=makeImage(IMG.wire,'gb-dec-wire','gb-dec-hidden',header);
const pine=makeImage(IMG.pine,'gb-dec-pine','gb-dec-hidden',header);
const canvas=document.createElement('canvas');canvas.id='gb-dec-glow';canvas.className='gb-dec-hidden';header.appendChild(canvas);
const ctx=canvas.getContext('2d');
const left=makeImage(IMG.left,'gb-dec-stroik-left','gb-dec-stroik gb-dec-stroik-left gb-dec-hidden',legend);
const right=makeImage(IMG.right,'gb-dec-stroik-right','gb-dec-stroik gb-dec-stroik-right gb-dec-hidden',legend);
const bulbs=[[177,60,'#fa2836'],[249,80,'#ffd52c'],[336,91,'#00ffdb'],[417,104,'#ff2336'],[494,100,'#ffe33d'],[573,88,'#68fa30'],[660,72,'#14e7fc']];
let run=false,last=0,random=bulbs.map(()=>Math.random()),randomAt=0,raf=0;
function syncSize(){const r=header.getBoundingClientRect();const width=r.width;
 if(!width)return;
 const dpr=Math.min(2,window.devicePixelRatio||1);
 canvas.width=Math.round(width*dpr);canvas.height=Math.round(width*145/841*dpr);
 canvas.style.width=width+'px';canvas.style.height=width*145/841+'px';
 ctx.setTransform(canvas.width/841,0,0,canvas.height/145,0,0);
}
function factor(i,t){switch(pref.mode){
 case 'steady':return 1;
 case 'wave':return .16+.84*(.5+.5*Math.cos(t*2.2-i*.82));
 case 'breath':return .3+.7*(.5+.5*Math.cos(t*1.25));
 case 'alternate':return (i+Math.floor(t*1.5))%2===0?1:.18;
 case 'random':return random[i];
 default:return .25+.75*(.5+.5*Math.cos(t*1.6-i*.63+Math.sin(t*.31)));
}}
function frame(now){if(!run){raf=0;return;}raf=requestAnimationFrame(frame);
 if(now-last<65)return;last=now;
 const t=now/1000;
 if(t-randomAt>.48){randomAt=t;random=random.map(()=>Math.random()*.9+.1)}
 ctx.clearRect(0,0,841,145);
 if(!pref.power||pref.brightness===0)return;
 ctx.globalCompositeOperation='screen';
 const b=pref.brightness/100;
 for(let i=0;i<bulbs.length;i++){
  const [x,y,c]=bulbs[i],intensity=b*factor(i,t);
  ctx.globalAlpha=Math.min(.92,.85*intensity);
  const g=ctx.createRadialGradient(x,y,3,x,y,47);
  g.addColorStop(0,c);g.addColorStop(.25,c);g.addColorStop(1,'transparent');
  ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,47,0,Math.PI*2);ctx.fill();
 }
 ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
}
function lights(){
 // Oryginalne kule sa tylko w tej warstwie; nie rysujemy zadnej drugiej zarowki.
 const opacity=(1-.7*pref.glass/100);
 wire.style.opacity=String(opacity);
 wire.style.filter=`brightness(${pref.power ? .55+.15*pref.brightness/100 : .3}) saturate(${pref.saturation/100})`;
 canvas.style.filter=`saturate(${pref.saturation/100})`;
 canvas.style.opacity=pref.power?'1':'0';
}
function show(on){
 for(const el of [wire,pine,canvas,left,right])el.classList.toggle('gb-dec-hidden',!on);
 legend.classList.toggle('gb-dec-legend',on);
 if(on){syncSize();lights();if(!run){run=true;raf=requestAnimationFrame(frame)}}
 else if(run){run=false;if(raf)cancelAnimationFrame(raf);raf=0;ctx.clearRect(0,0,841,145)}
}
function inject(){
 if(!december())return;
 const menu=settings.querySelector('.gb-menu');
 if(!menu||menu.querySelector('[data-gb-dec-menu]'))return;
 const tile=document.createElement('button');tile.type='button';tile.className='gb-menu-tile';tile.dataset.gbDecMenu='1';
 tile.innerHTML='<span class="gb-menu-icon">🎄</span><span>Motyw świąteczny</span><span class="gb-menu-arrow">›</span>';
 tile.onclick=()=>openHolidaySettings();menu.appendChild(tile);
}
let closeHolidaySettings=()=>{};
function openHolidaySettings(){
 if(!december()||settings.querySelector('#gb-dec-panel'))return;
 const old=Array.from(settings.children);old.forEach(x=>x.style.display='none');
 const panel=document.createElement('section');panel.id='gb-dec-panel';panel.className='gb-dec-settings';
 const opts=[['wave','Fala — od lewej do prawej'],['steady','Świecą stale'],['breath','Spokojny oddech'],['random','Losowe migotanie'],['alternate','Naprzemiennie'],['mix','Magia grudnia — MIX']];
 panel.innerHTML=`<h4 class="gb-dec-menu-heading">🎄 Motyw świąteczny</h4>
 <div class="gb-dec-card"><label class="gb-dec-line" for="gb-dec-power"><span>💡 Światełka</span><input type="checkbox" id="gb-dec-power"></label></div>
 <div class="gb-dec-card"><label for="gb-dec-mode">Efekt świecenia</label><select id="gb-dec-mode">${opts.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div>
 <div class="gb-dec-card"><label class="gb-dec-line" for="gb-dec-bright"><span>Jasność światełek</span><output id="gb-dec-bright-out">100%</output></label><input type="range" id="gb-dec-bright" min="0" max="100" step="1"></div>
 <div class="gb-dec-card"><label class="gb-dec-line" for="gb-dec-sat"><span>Nasycenie koloru lampek</span><output id="gb-dec-sat-out">100%</output></label><input type="range" id="gb-dec-sat" min="0" max="500" step="5"></div>
 <div class="gb-dec-card"><label class="gb-dec-line" for="gb-dec-glass"><span>Przezroczystość szkła</span><output id="gb-dec-glass-out">20%</output></label><input type="range" id="gb-dec-glass" min="0" max="100" step="1"></div>
 <p style="font-size:12px;margin:0;color:#64748b">Stroiki pozostają na 70%. Ustawienia zapisują się automatycznie. Ta sekcja znika 1 stycznia.</p>
 <button type="button" id="gb-dec-back" class="gb-dec-back">← Wróć do ustawień</button>`;
 settings.appendChild(panel);
 const get=id=>panel.querySelector('#'+id);
 const power=get('gb-dec-power'),mode=get('gb-dec-mode'),bright=get('gb-dec-bright'),glass=get('gb-dec-glass'),sat=get('gb-dec-sat');
 power.checked=pref.power;mode.value=pref.mode;bright.value=pref.brightness;glass.value=pref.glass;sat.value=pref.saturation;
 const update=()=>{pref.power=power.checked;pref.mode=mode.value;pref.brightness=Number(bright.value);pref.glass=Number(glass.value);pref.saturation=Number(sat.value);
 get('gb-dec-bright-out').textContent=pref.brightness+'%';get('gb-dec-glass-out').textContent=pref.glass+'%';get('gb-dec-sat-out').textContent=pref.saturation+'%';
 save();lights()};
 [power,mode,bright,glass,sat].forEach(el=>el.addEventListener('input',update));update();
 closeHolidaySettings=()=>{panel.remove();old.forEach(x=>x.style.display='');closeHolidaySettings=()=>{}};
 get('gb-dec-back').onclick=closeHolidaySettings;
}
const menuObserver=new MutationObserver(inject);menuObserver.observe(settings,{childList:true,subtree:true});
let lastSeason=null;
function sync(){const s=december();if(s!==lastSeason){lastSeason=s;show(s)}
 if(s)inject();else{closeHolidaySettings();settings.querySelector('[data-gb-dec-menu]')?.remove()}}
window.addEventListener('resize',syncSize,{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden){run=false;if(raf)cancelAnimationFrame(raf);raf=0}else if(december())show(true)});
window.addEventListener('pageshow',sync);setInterval(sync,2000);setTimeout(sync,150);
window.GBGrudzienMotyw={status:()=>({december:december(),preview,settings:{...pref},stroiki:'70%',garland:!!document.getElementById('gb-dec-wire')})};
})();
